from collections import deque
import bisect

class Solution:

	def minLaptops(self, n, start, end):
		arr = list(zip(start, end))
		arr.sort()
		count = 0
		s = deque()
		for i in range(n):
			if s and arr[i][0] >= s[0]:
				s.popleft()
			bisect.insort_left(s, arr[i][1])
		return len(s)
